export function createDebounce(fn, waitMs, { now = () => 0 } = {}) {
  // Keep the first bundle; later calls merge into it.
  let handle = null;
  let captured = null;
  return (...args) => {
    captured = captured ?? args;
    if (handle === null) {
      handle = () => {
        handle = null;
        fn(...captured);
      };
      handle();
    }
  };
}

